const featuredTrips = [
  { title: 'París', subtitle: 'La Ciudad de la Luz', dates: '25-28 de Junio', image: 'https://i.postimg.cc/TYb9CHdx/Paris.jpg', description: 'Vive el romance y el arte. Torre Eiffel, Louvre y el Sena.' },
  { title: 'Roma', subtitle: 'La Ciudad Eterna', dates: '29 Oct - 1 Nov', image: 'https://i.postimg.cc/wTNV0b6Z/Roma.jpg', description: 'Historia viva. Coliseo, Vaticano y la mejor gastronomía.' },
  { title: 'Dubái', subtitle: 'Lujo y Futuro', dates: '18-22 de Noviembre', image: 'https://i.postimg.cc/gkhDNBzb/Dubai.webp', description: 'Rascacielos imposibles, desierto mágico y compras de lujo.' }
];

const galleryImages = [
    "https://i.postimg.cc/7PGdr9HM/Whats-App-Image-2026-01-13-at-22-10-08-(1).jpg", "https://i.postimg.cc/447qRPf1/Whats-App-Image-2026-01-13-at-22-10-08-(2).jpg", "https://i.postimg.cc/VvCV9fG7/Whats-App-Image-2026-01-13-at-22-10-10.jpg",
    "https://i.postimg.cc/c1g2Ghxm/Whats-App-Image-2026-01-13-at-22-10-10-(1).jpg", "https://i.postimg.cc/Hnyh0YZ6/Whats-App-Image-2026-01-13-at-22-10-10-(2).jpg", "https://i.postimg.cc/cCnb7x9h/Whats-App-Image-2026-01-13-at-22-10-10-(3).jpg",
    "https://i.postimg.cc/rsrPGVZk/Whats-App-Image-2026-01-13-at-22-10-13.jpg", "https://i.postimg.cc/ZndMPb7D/Whats-App-Image-2026-01-13-at-22-10-13-(1).jpg", "https://i.postimg.cc/yxZbh1p1/Whats-App-Image-2026-01-13-at-22-10-14.jpg"
];

// --- GLOBAL VARIABLES ---
let currentBookingInterest = '';

// --- RENDERING ---
function isTripFinished(dateStr) {
    const months = {
        'Enero': 0, 'Febrero': 1, 'Marzo': 2, 'Abril': 3, 'Mayo': 4, 'Junio': 5,
        'Julio': 6, 'Agosto': 7, 'Septiembre': 8, 'Octubre': 9, 'Noviembre': 10, 'Diciembre': 11,
        'Oct': 9, 'Nov': 10, 'Dic': 11, 'Sept': 8, 'Ago': 7 
    };

    // Limpieza básica y búsqueda del mes
    const parts = dateStr.replace('-', ' ').replace(',', '').split(' ');
    let monthIndex = -1;

    // Buscamos el último mes mencionado en la cadena (para casos como "29 Oct - 1 Nov")
    for (let i = parts.length - 1; i >= 0; i--) {
        const word = parts[i].charAt(0).toUpperCase() + parts[i].slice(1).toLowerCase();
        if (months[word] !== undefined) {
            monthIndex = months[word];
            break;
        }
    }

    if (monthIndex === -1) return false;

    // Buscamos el último número (día de finalización)
    const numbers = dateStr.match(/\d+/g);
    if (!numbers) return false;
    const lastDay = parseInt(numbers[numbers.length - 1]);

    // Usamos el año actual para la comparación
    const now = new Date();
    const year = now.getFullYear();

    const tripEnd = new Date(year, monthIndex, lastDay);
    tripEnd.setHours(23, 59, 59); // Final del día

    return now > tripEnd;
}

function renderDestinations() {
    const grid = document.getElementById('destinations-grid');
    grid.innerHTML = destinations.map(d => {
        const finished = isTripFinished(d.location);

        return `
        <div id="dest-card-${d.id}" 
             onclick="${finished ? '' : `openDetailModal(${d.id})`}" 
             class="relative group bg-white rounded-3xl shadow-md transition-all duration-500 border border-transparent flex flex-col h-full ring-offset-4 ring-offset-trip-light ring-0 
             ${finished ? 'opacity-80 grayscale cursor-not-allowed' : 'hover:shadow-2xl hover:-translate-y-2 cursor-pointer hover:border-trip-ice hover:ring-2 ring-trip-ice'}">

            ${finished ? `
                <div class="absolute inset-0 z-20 overflow-hidden rounded-3xl pointer-events-none">
                    <div class="absolute inset-0 bg-white/20 backdrop-blur-[1px]"></div>
                    <div class="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2">
                        <span class="bg-red-600/90 text-white px-6 py-2 rounded-full font-bold text-lg shadow-xl border-2 border-white transform -rotate-12 inline-block whitespace-nowrap tracking-widest">
                            FINALIZADO
                        </span>
                    </div>
                </div>
            ` : ''}

            <div class="relative h-56 sm:h-64 overflow-hidden rounded-t-3xl">
                <img src="${d.image}" class="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110">
                <div class="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors"></div>
                <div class="absolute top-4 right-4 bg-white/90 backdrop-blur px-3 py-1 rounded-full text-xs font-bold flex gap-1 items-center z-10">
                    <i data-lucide="star" class="w-3 h-3 text-yellow-400 fill-current"></i> ${d.rating}
                </div>
            </div>
            <div class="p-5 flex flex-col flex-1">
                <div class="flex justify-between items-start mb-auto">
                   <div>
                       <h4 class="text-lg font-bold group-hover:text-trip-primary transition-colors">${d.title}</h4>
                       <p class="text-gray-500 text-xs flex gap-1 items-center mt-1"><i data-lucide="clock" class="w-3 h-3"></i> ${d.days} días</p>
                   </div>
                   <div class="text-right">
                       <p class="text-[10px] text-gray-400">Desde</p>
                       <p class="text-lg font-bold text-trip-primary">${d.price}€</p>
                   </div>
                </div>
                <div class="flex items-center justify-between pt-4 mt-4 border-t border-gray-100">
                     <span class="text-xs font-medium text-gray-500 flex items-center gap-2">
                        <i data-lucide="calendar" class="w-3 h-3 text-trip-secondary"></i> ${d.location}
                     </span>
                     <span class="text-sm font-semibold text-trip-black ${finished ? 'text-red-400' : 'hover:underline decoration-trip-primary'}">
                        ${finished ? 'Finalizado' : 'Más info'}
                     </span>
                </div>
            </div>
        </div>
    `}).join('');

    // Re-run icons for new elements
    if(window.lucide) window.lucide.createIcons();
}

function renderFeatured() {
     document.getElementById('featured-grid').innerHTML = featuredTrips.map(t => `
        <div onclick="openBookingModal('Interés en ${t.title}')" class="group relative h-[500px] rounded-[2rem] overflow-hidden cursor-pointer shadow-xl transition-transform duration-500 hover:-translate-y-2">
            <img src="${t.image}" class="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110">
            <div class="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent opacity-80 group-hover:opacity-90"></div>
            <div class="absolute bottom-0 left-0 w-full p-8 text-white transform translate-y-4 group-hover:translate-y-0 transition-transform duration-500">
                <p class="text-trip-tertiary font-medium mb-1 uppercase tracking-wider text-sm flex items-center gap-2"><i data-lucide="map-pin" class="w-3 h-3"></i> ${t.subtitle}</p>
                <h3 class="text-4xl font-display font-bold mb-4">${t.title}</h3>
                <div class="space-y-4">
                    <div class="flex items-center gap-3 bg-white/10 p-3 rounded-xl backdrop-blur-sm"><i data-lucide="calendar" class="text-trip-secondary w-5 h-5"></i> <span class="font-semibold text-lg">${t.dates}</span></div>
                    <p class="text-gray-300 text-sm opacity-0 group-hover:opacity-100 transition-opacity delay-100">${t.description}</p>
                    <button class="w-full bg-white text-trip-black font-bold py-3 rounded-xl hover:bg-trip-secondary hover:text-white transition-colors mt-4">Consultar Disponibilidad</button>
                </div>
            </div>
        </div>
     `).join('');
}

function renderOfferBar() {
    const container = document.getElementById('offer-bar-content');

    // Definimos los elementos de la oferta
    const items = [
        { icon: 'flame', color: 'text-yellow-300', text: 'OFERTAS 2026' },
        { icon: 'alert-triangle', color: 'text-orange-300', text: 'PLAZAS LIMITADAS' },
        { icon: 'plane', color: 'text-trip-ice', text: '¡RESERVA HOY!' },
        { icon: 'star', color: 'text-yellow-400', text: 'MEJORES DESTINOS' },
        { icon: 'gift', color: 'text-pink-300', text: 'DESCUENTOS GRUPALES' }
    ];

    // Generamos el HTML de un bloque de items
    const generateBlock = () => items.map(item => `
        <div class="flex items-center gap-3 mx-8 md:mx-12">
            <i data-lucide="${item.icon}" class="${item.color} w-5 h-5 md:w-6 md:h-6"></i>
            <span class="font-bold uppercase text-xs md:text-sm whitespace-nowrap tracking-widest text-white/90">${item.text}</span>
        </div>
    `).join('');

    const contentBlock = generateBlock();

    // Insertamos dos bloques idénticos con la animación de marquee
    const trackClass = "flex items-center animate-marquee min-w-full flex-shrink-0 justify-around py-1";

    container.innerHTML = `
        <div class="${trackClass}">
            ${contentBlock}
        </div>
        <div class="${trackClass}" aria-hidden="true">
            ${contentBlock}
        </div>
    `;

    // Reinicializamos los iconos para el nuevo contenido inyectado
    if(window.lucide) window.lucide.createIcons();
}

function renderGallery() {
    const container = document.getElementById('gallery-container');
    const images = [...galleryImages, ...galleryImages]; // Double for seamless
    container.innerHTML = images.map(src => `
       <div class="relative h-64 w-48 md:h-80 md:w-64 flex-shrink-0 rounded-2xl overflow-hidden shadow-lg border-2 border-white transform hover:scale-95 transition-transform select-none">
           <img src="${src}" class="h-full w-full object-cover pointer-events-none draggable-none" ondragstart="return false;">
       </div>
    `).join('');
    container.classList.add('cursor-grab', 'active:cursor-grabbing');
}

function initGalleryScroll() {
    const container = document.getElementById('gallery-container');
    let isDown = false;
    let startX;
    let scrollLeft;
    let isPaused = false;
    const speed = 0.5;

    const animate = () => {
        if (!isDown && !isPaused) {
            container.scrollLeft += speed;
        }

        // Infinite Loop Logic
        const maxScroll = container.scrollWidth / 2;

        if (container.scrollLeft >= maxScroll) {
            container.scrollLeft = container.scrollLeft - maxScroll;
        } else if (container.scrollLeft <= 0) {
             // For manual dragging left, though basic auto scroll goes right
        }

        requestAnimationFrame(animate);
    };

    // Mouse Events
    container.addEventListener('mousedown', (e) => {
        isDown = true;
        isPaused = true;
        container.classList.add('cursor-grabbing');
        container.classList.remove('cursor-grab');
        startX = e.pageX - container.offsetLeft;
        scrollLeft = container.scrollLeft;
    });

    container.addEventListener('mouseleave', () => {
        isDown = false;
        isPaused = false;
        container.classList.remove('cursor-grabbing');
        container.classList.add('cursor-grab');
    });

    container.addEventListener('mouseup', () => {
        isDown = false;
        isPaused = false;
        container.classList.remove('cursor-grabbing');
        container.classList.add('cursor-grab');
    });

    container.addEventListener('mousemove', (e) => {
        if (!isDown) return;
        e.preventDefault();
        const x = e.pageX - container.offsetLeft;
        const walk = (x - startX) * 2; 
        container.scrollLeft = scrollLeft - walk;
    });

    // Touch Events
    container.addEventListener('touchstart', (e) => {
        isDown = true;
        isPaused = true;
        startX = e.touches[0].pageX - container.offsetLeft;
        scrollLeft = container.scrollLeft;
    }, {passive: true});

    container.addEventListener('touchend', () => {
        isDown = false;
        isPaused = false;
    });

    container.addEventListener('touchmove', (e) => {
        if (!isDown) return;
        const x = e.touches[0].pageX - container.offsetLeft;
        const walk = (x - startX) * 2;
        container.scrollLeft = scrollLeft - walk;
    }, {passive: true});

    // Hover Pause
    container.addEventListener('mouseenter', () => isPaused = true);

    requestAnimationFrame(animate);
}

// --- MODALS ---
window.openModal = (id) => {
     document.getElementById(id).classList.remove('hidden');
     setTimeout(() => document.getElementById(id).classList.add('open'), 10);
     document.body.style.overflow = 'hidden';
};

window.closeModal = (id) => {
     document.getElementById(id).classList.remove('open');
     setTimeout(() => document.getElementById(id).classList.add('hidden'), 300);
     document.body.style.overflow = 'auto';
};

window.openBookingModal = (interest = '') => {
    currentBookingInterest = interest;
    openModal('booking-modal');
};

window.redirectToWhatsApp = () => {
    const phone = "34649866985";
    const msg = currentBookingInterest 
        ? `Hola Tereviajes, me interesa: *${currentBookingInterest}*.` 
        : "Hola Tereviajes, quiero información para mi próximo viaje.";
    window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`, '_blank');
    closeModal('booking-modal');
};

window.openDetailModal = (id) => {
     const d = destinations.find(x => x.id == id);
     if(!d) return;
     document.getElementById('detail-img').src = d.image;
     document.getElementById('detail-rating').innerText = d.rating;
     document.getElementById('detail-title').innerText = d.title;
     document.getElementById('detail-price').innerText = d.price + '€';
     document.getElementById('detail-date').innerText = d.location;
     document.getElementById('detail-days').innerText = d.days + (d.days===1?' Día':' Días');
     document.getElementById('detail-desc').innerText = d.description;
     openModal('detail-modal');
};

function renderCalendar() {
    // Group by month logic simplified
    const container = document.getElementById('calendar-content');
    const grouped = {};
    destinations.forEach(d => {
        const month = d.location.split(' ').pop();
        if(!grouped[month]) grouped[month] = [];
        grouped[month].push(d);
    });
    // Manual sort order
    const months = ['Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre'];

    container.innerHTML = months.filter(m => grouped[m]).map(m => `
         <div>
            <h3 class="text-2xl font-bold text-trip-black mb-4 border-b border-gray-200 pb-2">${m}</h3>
            <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
                ${grouped[m].map(d => {
                    const finished = isTripFinished(d.location);
                    return `
                    <div onclick="${finished ? '' : `closeModal('calendar-modal'); openBookingModal('${d.title}')`}" 
                         class="bg-white p-4 rounded-2xl border border-gray-100 flex items-center gap-4 ${finished ? 'opacity-60 grayscale cursor-not-allowed' : 'hover:shadow-md cursor-pointer'}">
                        <div class="relative">
                            <img src="${d.image}" class="w-16 h-16 rounded-xl object-cover">
                            ${finished ? '<div class="absolute inset-0 bg-white/50 flex items-center justify-center"><i data-lucide="lock" class="w-4 h-4 text-gray-800"></i></div>' : ''}
                        </div>
                        <div>
                            <h4 class="font-bold ${finished ? 'line-through text-gray-400' : ''}">${d.title}</h4>
                            <p class="text-xs text-gray-500">${d.location}</p>
                        </div>
                        <div class="ml-auto font-bold ${finished ? 'text-gray-400' : 'text-trip-primary'}">${d.price}€</div>
                    </div>
                `}).join('')}
            </div>
         </div>
    `).join('');
}
window.openCalendarModal = () => openModal('calendar-modal');
